package com.example.starter.firmware.domain;

/**
 * 双分区发布单状态：ACTIVE 投放中；PAUSED 已暂停（禁止新试启动，不撤销已有 TRIAL 的健康确认）。
 */
public enum DualReleaseStatus {
    ACTIVE,
    PAUSED
}

package com.example.starter.firmware.domain;

/**
 * 双分区试启动任务状态：PENDING 待试启动；TRIAL 试启动中（60秒内待健康确认）；
 * COMMITTED 已正式切换（终态）；ROLLED_BACK 已回滚（终态）。
 */
public enum DualTaskStatus {
    PENDING,
    TRIAL,
    COMMITTED,
    ROLLED_BACK
}

package com.example.starter.firmware.domain;

/**
 * 双分区任务回滚原因：EXPIRED 试启动后60秒内未收到健康确认；FAILED 设备上报试启动失败。
 */
public enum RollbackReason {
    EXPIRED,
    FAILED
}

package com.example.starter.firmware.domain;

/**
 * 双分区试启动发布单。
 *
 * @param id              发布单ID
 * @param version         发布单版本号，从1开始，暂停成功加一
 * @param model           目标设备型号
 * @param targetVersion   目标固件版本，健康确认通过后切换
 * @param status          状态：ACTIVE 投放中，PAUSED 已暂停
 * @param committedCount  首次进入 COMMITTED 的任务数，每任务只计一次
 * @param rolledBackCount 首次进入 ROLLED_BACK 的任务数（含失败与到期），每任务只计一次
 */
public record DualRelease(long id, int version, String model, String targetVersion,
                          DualReleaseStatus status, int committedCount, int rolledBackCount) {
}

package com.example.starter.firmware.domain;

/**
 * 设备启动分区状态。无记录时视为分区 A。
 *
 * @param deviceId         设备ID
 * @param currentPartition 当前启动分区：A 或 B
 */
public record DeviceBootState(String deviceId, String currentPartition) {

    public static final String DEFAULT_PARTITION = "A";

    /**
     * 另一分区：当前为 A 时返回 B，否则返回 A。
     */
    public static String otherPartition(String currentPartition) {
        return DEFAULT_PARTITION.equals(currentPartition) ? "B" : DEFAULT_PARTITION;
    }
}

