    @Test
    void 到期60秒确认409_仍为v1_回滚只记录一次_重试产生新任务ID() throws Exception {
        registerDevice("r-dev", "d1", "m1", "v1");
        long releaseId = createDualRelease("r-rel", "m1", "v2");
        long taskId = dualPull("r-pull", "d1");
